package io.github.yuroyami.kitepdf

import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/**
 * Encrypted PDFs that qpdf 12.4.2 wrote, through pikepdf 10.18.0 (#908), and one with /StmF /Identity that
 * qpdf cannot write but opens (#796). Written by
 * `tools/encrypted_fixtures.py`; regenerate them with it, not by hand. Each shows its [Fixture.name] on its
 * page, as its /Info title and as its XMP dc:title. The user password is "user", or empty where
 * [Fixture.userPassword] is, and the owner password "owner".
 */
@OptIn(ExperimentalEncodingApi::class)
internal object EncryptedFixtures {

    class Fixture(val name: String, val userPassword: String, val revision: Int, val objectStreams: Boolean, val encryptsMetadata: Boolean, base64: String) {
        val bytes: ByteArray by lazy { Base64.decode(base64) }
    }

    val all: List<Fixture> = listOf(
        Fixture("R3 RC4-128 classic", "user", 3, false, true,
            ""),
        Fixture("R3 RC4-128 object streams", "user", 3, true, true,
            ""),
        Fixture("R4 AES-128 classic", "user", 4, false, true,
            ""),
        Fixture("R4 AES-128 object streams", "user", 4, true, true,
            ""),
        Fixture("R6 AES-256 classic", "user", 6, false, true,
            ""),
        Fixture("R6 AES-256 object streams", "user", 6, true, true,
            ""),
        Fixture("R4 AES-128 plain metadata", "user", 4, false, false,
            ""),
        Fixture("R4 AES-128 owner only", "", 4, false, true,
            ""),
        Fixture("R6 AES-256 owner only", "", 6, true, true,
            ""),
        Fixture("R4 AES-128 identity streams", "user", 4, false, true,
            ""),
        Fixture("R6 AES-256 identity streams", "user", 6, false, true,
            ""),
    )
}
